<template>
    <section>
        <header class="coop-head"><h2>业务配置</h2><div class="coop-actions"><el-button :disabled="saving" @click="channelsVisible=true">ERP 登录渠道</el-button><el-button v-if="canViewNotice" :disabled="saving" @click="noticeVisible=true">通知渠道</el-button><el-button v-if="canEditCatalog" :disabled="saving" @click="catalogVisible=true">需求型号清单</el-button><el-button :icon="Refresh" :loading="loading" :disabled="saving" @click="reload">重新读取</el-button></div></header>
        <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="coop-error" />
        <el-skeleton v-if="loading&&!ready" :rows="8" animated />
        <template v-if="ready">
            <el-alert v-if="!form.fee_confirmed" title="平台费规则尚未确认，商户不能创建协作佣金支付单。请先核对下方比例和最低费用，再明确确认。" type="warning" show-icon closable class="coop-error" />
            <el-form label-position="top" class="coop-form" :disabled="saving||loading">
                <section class="coop-surface"><div class="coop-section-caption"><h3>1. 业务开关与发单权益</h3><el-switch v-model="form.enabled" active-text="允许商户协作" /></div><div class="coop-rule-grid"><el-form-item label="发单需购买权益"><el-switch v-model="form.publishing_required" /><p class="coop-form-note">开启后检查商户有效期；关闭即不要求付费权益，不取消已形成订单。</p></el-form-item><el-form-item label="一个月发单权益价格（元）"><el-input-number v-model="form.publishing_price" :min="0" :precision="2" :step="10" :disabled="!form.publishing_required" controls-position="right" /><p class="coop-form-note">从购买时起算一个月，月末按目标月最后一天；不是按自然月结束。启用收费时价格须大于0。</p></el-form-item></div></section>
                <section class="coop-surface" style="margin-top:14px"><div class="coop-section-caption"><h3>2. 成交付佣与平台维护费</h3><el-tag type="info" effect="plain">不核算门店利润</el-tag></div><div class="coop-rule-grid"><el-form-item label="成交最低协作佣金（元）"><el-input-number v-model="form.commission_minimum" :min="50" :precision="2" controls-position="right" @change="form.fee_confirmed=false" /><p class="coop-form-note">至少50元；未成交不收费，不要求填写成交额或利润。</p></el-form-item><el-form-item label="平台维护费比例（%）"><el-input-number v-model="form.fee_percent" :min="0" :max="99.99" :precision="2" controls-position="right" @change="form.fee_confirmed=false" /><p class="coop-form-note">对实际支付的协作佣金计算，不是对客户货款或利润计算。</p></el-form-item><el-form-item label="每笔最低平台维护费（元）"><el-input-number v-model="form.fee_minimum" :min="0" :precision="2" controls-position="right" @change="form.fee_confirmed=false" /><p class="coop-form-note">平台费不超过本笔佣金；剩余部分才形成发布方收益。</p></el-form-item><el-form-item label="分账示例（只预览，不产生订单）"><div class="coop-readout">若付佣 {{ coopMoney(form.commission_minimum) }}<br />平台维护费 {{ coopMoney(preview.fee) }}<br />发布方净收益 {{ coopMoney(preview.net) }}</div></el-form-item></div><el-checkbox v-model="form.fee_confirmed">我已确认上述收费口径，允许新支付单按这套规则计算</el-checkbox></section>
                <section class="coop-surface" style="margin-top:14px"><div class="coop-section-caption"><h3>3. 靠谱认证</h3></div><div class="coop-rule-grid"><el-form-item label="认证价格（元）"><el-input-number v-model="form.certification_price" :min="0" :precision="2" controls-position="right" /><p class="coop-form-note">未设置有效价格时不开放购买。人工授予在“商户资格”中登记原因。</p></el-form-item><el-form-item label="认证有效期"><el-radio-group v-model="permanentCertification"><el-radio :value="true">永久有效</el-radio><el-radio :value="false">指定期限</el-radio></el-radio-group><el-input-number v-if="!permanentCertification" v-model="form.certification_months" :min="1" :max="120" :precision="0" controls-position="right" aria-label="认证有效月数" /><p class="coop-form-note">{{ permanentCertification ? '核验通过后长期有效，平台仍可撤销认证或停止合作。' : '按购买时起算，填写 1—120 个月；付款后仍需平台核验。' }}只影响新购买，不改已保存的认证期限。</p></el-form-item></div><p class="coop-muted">认证与交付等级分别排序。认证不等于保证现货、保证成交或平台赔付。</p></section>
                <section class="coop-surface" style="margin-top:14px"><div class="coop-section-caption"><h3>4. 商户交付等级</h3><el-button :icon="Plus" @click="addGrade">添加等级</el-button></div><p class="coop-muted" style="margin-bottom:14px">按有效在售库存记录自动匹配；可在商户资格中人工指定。库存成色不等于商户等级。</p><HsxTable :columns="gradeColumns" :data="form.grades" row-key="id" empty-text="请先添加至少一个有效商户等级">
                    <template #name="{row}"><el-input v-model="row.name" maxlength="20" placeholder="如S级商户" /></template>
                    <template #rank="{row}"><el-input-number v-model="row.rank" :min="0" :max="9999" :precision="0" controls-position="right" style="width:100%" /></template>
                    <template #inventory="{row}"><el-input-number v-model="row.min_inventory" :min="0" :max="9999999" :precision="0" controls-position="right" style="width:100%" /></template>
                    <template #capability="{row}"><el-checkbox v-model="row.all_models" :disabled="Number(row.rank)!==highestRank&&!row.all_models" >全型号承接</el-checkbox><el-tooltip v-if="Number(row.rank)!==highestRank" content="只有当前最高排序等级可开启；已有勾选仍可取消，不表示锁货或实物现货"><span class="coop-muted">仅最高级可用</span></el-tooltip></template>
                    <template #status="{row}"><el-switch v-model="row.status" /></template>
                    <template #action="{row}"><el-button link type="danger" @click="removeGrade(row)">移除</el-button></template>
                </HsxTable><p class="coop-form-note">库存门槛是首配建议，请按实际业务核定后保存启用。排序值越大等级越高；同地区内仍先看有效靠谱认证。最高等级的全型号能力仍可关闭，不代表现货或锁货。移除已使用等级前需先调整对应商户，服务端会再次校验。</p></section>
                <section class="coop-surface" style="margin-top:14px"><div class="coop-section-caption"><h3>5. 跟进提醒与库存有效性</h3></div><div class="coop-rule-grid"><el-form-item label="接单关注时限（分钟）"><el-input-number v-model="form.response_minutes" :min="0" :max="10080" :precision="0" controls-position="right" /><p class="coop-form-note">超过后供平台关注，不自动判定未成交或飞单。填0表示不设置此时限。</p></el-form-item><el-form-item label="联系客户关注时限（小时）"><el-input-number v-model="form.contact_hours" :min="0" :max="720" :precision="0" controls-position="right" /></el-form-item><el-form-item label="结果回填关注时限（小时）"><el-input-number v-model="form.review_hours" :min="0" :max="2160" :precision="0" controls-position="right" /><p class="coop-form-note">供客服筛选跟进，不据此自动停用门店。</p></el-form-item><el-form-item label="库存快照有效期（小时）"><el-input-number v-model="form.inventory_fresh_hours" :min="1" :max="168" :precision="0" controls-position="right" /><p class="coop-form-note">超期或来源状态不明的库存不作为可交付现货依据。</p></el-form-item></div></section>
                <section class="coop-surface" style="margin-top:14px"><div class="coop-section-caption"><h3>客户需求型号</h3></div><el-form-item label="每条线索最多选择的型号数"><el-input-number v-model="form.demand_model_limit" :min="0" :max="5000" :precision="0" controls-position="right" /><p class="coop-form-note">建议3—5个；填0不设置业务数量限制。仅限制客户发布需求，不限制门店登记交付能力。多项需求在手机端折叠展示。</p></el-form-item></section>
            </el-form>
            <footer class="coop-config-footer"><p>只保存本站规则，不发起付款、通知、ERP同步或真实转账。</p><el-button type="primary" :loading="saving" :disabled="loading" @click="save">保存业务配置</el-button></footer>
        </template>
        <CatalogDrawer v-if="canEditCatalog" v-model="catalogVisible" />
        <ProviderChannelsSettings v-model="channelsVisible" :can-edit="canManageChannels" />
        <NoticeSettings v-if="canViewNotice" v-model="noticeVisible" :can-edit="canEditNotice" />
    </section>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Refresh } from '@element-plus/icons-vue'
import HsxTable from '@/addon/hsx_components/components/HsxTable/index.vue'
import useUserStore from '@/stores/modules/user'
import CatalogDrawer from '../components/CatalogDrawer.vue'
import ProviderChannelsSettings from '../components/ProviderChannelsSettings.vue'
import NoticeSettings from '../components/NoticeSettings.vue'
import { hasLeadPagePermission } from '../../composables/navigation'
import { getCooperationConfig, saveCooperationConfig } from '../../api/cooperation'
import { coopError, coopMoney, type CoopRow } from '../../composables/cooperation'
const loading=ref(false),saving=ref(false),ready=ref(false),error=ref(''),form=reactive<CoopRow>({grades:[]});let sequence=0,disposed=false,baseline=''
const user=useUserStore(),catalogVisible=ref(false)
const channelsVisible=ref(false),canManageChannels=computed(()=>hasLeadPagePermission(user,'hsx_lead_cooperation_config_save'))
const noticeVisible=ref(false),canViewNotice=computed(()=>hasLeadPagePermission(user,'hsx_lead_manage_notice_config'))
const canEditNotice=computed(()=>hasLeadPagePermission(user,'hsx_lead_manage_notice_config_save'))
const canEditCatalog=computed(()=>hasLeadPagePermission(user,'hsx_lead_manage_catalog')&&hasLeadPagePermission(user,'hsx_lead_manage_catalog_save'))
const permanentCertification=computed({get:()=>Number(form.certification_months)===0,set:(value:boolean)=>{form.certification_months=value?0:12}})
const highestRank=computed(()=>Math.max(0,...(form.grades||[]).filter((grade:CoopRow)=>grade.status).map((grade:CoopRow)=>Number(grade.rank)||0)))
const preview=computed(()=>{const amount=Math.round(Number(form.commission_minimum||0)*100),fee=Math.min(amount,Math.max(Math.round(amount*Number(form.fee_percent||0)/100),Math.round(Number(form.fee_minimum||0)*100)));return{fee:fee/100,net:(amount-fee)/100}})
const gradeColumns=[{prop:'name',label:'等级名称',slot:'name',minWidth:150},{prop:'rank',label:'排序（越大越高）',slot:'rank',minWidth:150},{prop:'min_inventory',label:'最低库存记录数',slot:'inventory',minWidth:160},{prop:'all_models',label:'交付能力',slot:'capability',minWidth:220},{prop:'status',label:'启用',slot:'status',width:80},{prop:'action',label:'操作',slot:'action',width:70}]
function normalize(data:CoopRow){const result=JSON.parse(JSON.stringify(data));for(const field of ['enabled','publishing_required','fee_confirmed'])result[field]=!!result[field];for(const field of ['publishing_price','certification_price','commission_minimum','fee_percent','fee_minimum','certification_months','response_minutes','contact_hours','review_hours','inventory_fresh_hours'])result[field]=Number(result[field]??0);result.demand_model_limit=Number(result.demand_model_limit??5);result.grades=(Array.isArray(result.grades)?result.grades:[]).map((grade:CoopRow)=>({...grade,id:String(grade.id),rank:Number(grade.rank),min_inventory:Number(grade.min_inventory),status:!!grade.status,all_models:!!grade.all_models}));return result}
async function load(){const token=++sequence;loading.value=true;error.value='';try{const result=await getCooperationConfig();if(token!==sequence||disposed)return;const data=normalize(result.data||{});if(!Array.isArray(data.grades))throw new Error('未返回有效配置');Object.keys(form).forEach(key=>delete form[key]);Object.assign(form,data);baseline=JSON.stringify(form);ready.value=true}catch(cause){if(token===sequence&&!disposed)error.value=coopError(cause,'配置读取失败，请确认具备业务配置权限')}finally{if(token===sequence&&!disposed)loading.value=false}}
async function reload(){if(saving.value)return;if(ready.value&&JSON.stringify(form)!==baseline){try{await ElMessageBox.confirm('重新读取会覆盖本页尚未保存的修改，是否继续？','保留修改或重新读取',{confirmButtonText:'放弃修改并读取',cancelButtonText:'继续编辑',type:'warning'})}catch{return}}await load()}
function addGrade(){form.grades.push({id:`grade_${Date.now().toString(36)}`,name:'',rank:0,min_inventory:0,all_models:false,status:true})}
async function removeGrade(row:CoopRow){try{await ElMessageBox.confirm(`移除“${row.name||'未命名等级'}”？只有保存配置后才生效，已使用等级的移除仍需服务端核对。`,'移除等级',{type:'warning',confirmButtonText:'从本次配置移除'})}catch{return}form.grades=form.grades.filter((grade:CoopRow)=>grade.id!==row.id)}
function validation(){if(form.publishing_required&&Number(form.publishing_price)<=0)return'开启付费发单时，请填写大于0的一个月权益价格';if(Number(form.commission_minimum)<50)return'成交最低佣金不能小于50元';if(Number(form.fee_percent)>=100||Number(form.fee_minimum)>=Number(form.commission_minimum))return'平台费比例须低于100%，最低平台费须小于最低佣金';if(!form.grades.length||!form.grades.some((grade:CoopRow)=>grade.status))return'至少需要一个启用的商户等级';const ids=new Set(),ranks=new Set();for(const grade of form.grades){if(!String(grade.name).trim())return'请填写每个等级的名称';if(ids.has(grade.id))return'等级标识重复，请重新添加';ids.add(grade.id);if(ranks.has(Number(grade.rank)))return'每个等级的排序值必须不同';ranks.add(Number(grade.rank));if(grade.all_models&&Number(grade.rank)!==highestRank.value)return'只有最高等级可以授予全型号承接能力，请先核对勾选'}return''}
async function save(){if(saving.value||loading.value||!ready.value)return;error.value=validation();if(error.value)return;saving.value=true;try{const payload=JSON.parse(JSON.stringify(form));for(const key of ['publishing_price','certification_price','commission_minimum','fee_percent','fee_minimum'])payload[key]=Number(payload[key]).toFixed(2);const result=await saveCooperationConfig(payload);const saved=normalize(result.data||payload);Object.assign(form,saved);baseline=JSON.stringify(form);ElMessage.success('本站业务配置已保存，已有支付单金额不回写')}catch(cause){error.value=coopError(cause,'保存未完成，已保留全部修改')}finally{saving.value=false}}
onMounted(load);onBeforeUnmount(()=>{disposed=true;sequence++})
</script>
